def sum_tree(root):
    if root is None:
        return 0
    total = 0
    stack = [root]
    while stack:  # ✅ iterative — no recursion limit
        node = stack.pop()
        total += node.val
        if node.left:  stack.append(node.left)
        if node.right: stack.append(node.right)
    return total

